WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY discount NULLS LAST, id) AS rank_in_group FROM orders QUALIFY rank_in_group = 1) SELECT customer_id, DATE_TRUNC('MONTH', order_date) AS activity_month, CORR(shipping_fee, amount) AS corr_shipping_fee_amount, CORR(discount, amount) AS corr_discount_amount, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN channel = 'store' THEN 1 END), 0), 2) AS discount_per_store, ROUND(AVG(shipping_fee), 2) AS avg_shipping_fee, COUNT_IF(status = 'PENDING') AS pending_events, CORR(amount, shipping_fee) AS corr_amount_shipping_fee, GROUPING(customer_id) AS grouping_id FROM ranked GROUP BY CUBE (customer_id, DATE_TRUNC('MONTH', order_date)) ORDER BY corr_amount_shipping_fee DESC NULLS LAST;
